const clients = new Map();
const rooms = new Map();

class WebSocketManager {
  static broadcast(room, message, excludeId = null) {
    const roomClients = rooms.get(room) || new Set();

    roomClients.forEach((clientId) => {
      if (clientId !== excludeId) {
        const client = clients.get(clientId);
        if (client && client.readyState === WebSocket.OPEN) {
          client.send(JSON.stringify(message));
        }
      }
    });
  }

  static joinRoom(clientId, room) {
    if (!rooms.has(room)) {
      rooms.set(room, new Set());
    }
    rooms.get(room).add(clientId);

    this.broadcast(room, {
      type: 'user-joined',
      userId: clientId,
      roomId: room,
    });
  }

  static leaveRoom(clientId, room) {
    const roomClients = rooms.get(room);
    if (roomClients) {
      roomClients.delete(clientId);
      if (roomClients.size === 0) {
        rooms.delete(room);
      } else {
        this.broadcast(room, {
          type: 'user-left',
          userId: clientId,
          roomId: room,
        });
      }
    }
  }
}

wss.on('connection', (ws, req) => {
  const clientId = generateId();
  clients.set(clientId, ws);

  console.log(`Client ${clientId} connected`);

  ws.on('message', (data) => {
    try {
      const message = JSON.parse(data);

      switch (message.type) {
        case 'join':
          WebSocketManager.joinRoom(clientId, message.room);
          ws.send(JSON.stringify({
            type: 'joined',
            roomId: message.room,
            clientId,
          }));
          break;

        case 'leave':
          WebSocketManager.leaveRoom(clientId, message.room);
          break;

        case 'message':
          WebSocketManager.broadcast(
            message.room,
            {
              type: 'message',
              content: message.content,
              userId: clientId,
              timestamp: new Date().toISOString(),
            },
            clientId
          );
          break;

        default:
          console.log('Unknown message type:', message.type);
      }
    } catch (error) {
      console.error('Error processing message:', error);
    }
  });

  ws.on('close', () => {
    console.log(`Client ${clientId} disconnected`);

    // Remove from all rooms
    rooms.forEach((roomClients, room) => {
      if (roomClients.has(clientId)) {
        WebSocketManager.leaveRoom(clientId, room);
      }
    });

    clients.delete(clientId);
  });

  ws.on('error', (error) => {
    console.error(`WebSocket error for client ${clientId}:`, error);
  });

  // Send welcome message
  ws.send(JSON.stringify({
    type: 'welcome',
    clientId,
  }));
});

