import { io, Socket } from 'socket.io-client';
import { useEffect, useState, useCallback } from 'react';

interface Message {
  id: string;
  content: string;
  userId: string;
  timestamp: string;
}

function useSocket(url: string) {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [connected, setConnected] = useState(false);

  useEffect(() => {
    const newSocket = io(url, {
      reconnection: true,
      reconnectionDelay: 1000,
      reconnectionAttempts: 5,
    });

    newSocket.on('connect', () => {
      console.log('Socket connected');
      setConnected(true);
    });

    newSocket.on('disconnect', () => {
      console.log('Socket disconnected');
      setConnected(false);
    });

    setSocket(newSocket);

    return () => {
      newSocket.close();
    };
  }, [url]);

  return { socket, connected };
}

function ChatRoom({ roomId }: { roomId: string }) {
  const { socket, connected } = useSocket('http://localhost:3000');
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [users, setUsers] = useState<string[]>([]);

  useEffect(() => {
    if (!socket) return;

    socket.emit('join-room', roomId);

    socket.on('message', (message: Message) => {
      setMessages((prev) => [...prev, message]);
    });

    socket.on('user-joined', ({ userId }: { userId: string }) => {
      setUsers((prev) => [...prev, userId]);
    });

    socket.on('user-left', ({ userId }: { userId: string }) => {
      setUsers((prev) => prev.filter((id) => id !== userId));
    });

    socket.on('room-users', ({ users }: { users: string[] }) => {
      setUsers(users);
    });

    return () => {
      socket.emit('leave-room', roomId);
      socket.off('message');
      socket.off('user-joined');
      socket.off('user-left');
      socket.off('room-users');
    };
  }, [socket, roomId]);

  const sendMessage = useCallback(() => {
    if (!socket || !inputValue.trim()) return;

    socket.emit('send-message', {
      roomId,
      content: inputValue,
    });

    setInputValue('');
  }, [socket, roomId, inputValue]);

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  return (
    <div className="chat-room">
      <div className="users-panel">
        <h3>Users ({users.length})</h3>
        <ul>
          {users.map((userId) => (
            <li key={userId}>{userId}</li>
          ))}
        </ul>
      </div>

      <div className="messages-panel">
        <div className="messages">
          {messages.map((msg) => (
            <div key={msg.id} className="message">
              <strong>{msg.userId}:</strong> {msg.content}
              <span className="timestamp">{msg.timestamp}</span>
            </div>
          ))}
        </div>

        <div className="input-area">
          <input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder="Type a message..."
            disabled={!connected}
          />
          <button onClick={sendMessage} disabled={!connected}>
            Send
          </button>
        </div>
      </div>
    </div>
  );
}

class ErrorHandler extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends ErrorHandler {
  constructor(message) {
    super(message, 400);
  }
}

class UnauthorizedError extends ErrorHandler {
  constructor(message = 'Unauthorized') {
    super(message, 401);
  }
}

class ForbiddenError extends ErrorHandler {
  constructor(message = 'Forbidden') {
    super(message, 403);
  }
}

class NotFoundError extends ErrorHandler {
  constructor(message = 'Resource not found') {
    super(message, 404);
  }
}

const errorHandler = (err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  if (process.env.NODE_ENV === 'development') {
    sendErrorDev(err, res);
  } else {
    let error = { ...err };
    error.message = err.message;

    // Mongoose bad ObjectId
    if (err.name === 'CastError') {
      error = new ValidationError(`Invalid ${err.path}: ${err.value}`);
    }

    // Mongoose duplicate key
    if (err.code === 11000) {
      const field = Object.keys(err.keyValue)[0];
      error = new ValidationError(`Duplicate field value: ${field}`);
    }

    // Mongoose validation error
    if (err.name === 'ValidationError') {
      const errors = Object.values(err.errors).map((e) => e.message);
      error = new ValidationError(`Invalid input data: ${errors.join(', ')}`);
    }

    // JWT errors
    if (err.name === 'JsonWebTokenError') {
      error = new UnauthorizedError('Invalid token');
    }

    if (err.name === 'TokenExpiredError') {
      error = new UnauthorizedError('Token expired');
    }

    sendErrorProd(error, res);
  }
};

const sendErrorDev = (err, res) => {
  res.status(err.statusCode).json({
    status: err.status,
    error: err,
    message: err.message,
    stack: err.stack,
  });
};

const sendErrorProd = (err, res) => {
  if (err.isOperational) {
    res.status(err.statusCode).json({
      status: err.status,
      message: err.message,
    });
  } else {
    console.error('ERROR:', err);
    res.status(500).json({
      status: 'error',
      message: 'Something went wrong',
    });
  }
};

module.exports = {
  ErrorHandler,
  ValidationError,
  UnauthorizedError,
  ForbiddenError,
  NotFoundError,
  errorHandler,
};

